targets.query:
from(bucket: "alerts")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "soc_alert" and r._field == "risk_score")
  // Points written before model_used became a tag carry no value for it, and
  // Flux groups those under null -- an unlabelled slice in the chart. Name them
  // instead, so the gap reads as missing instrumentation rather than a branch.
  |> map(fn: (r) => ({r with model_used:
       if exists r.model_used then r.model_used else "before instrumentation"}))
  |> group(columns: ["model_used"])
  |> count()
  |> rename(columns: {_value: "alerts"})
